"""Tune inverse diffusion PIKAN."""
import argparse,json,optuna,torch
from PIKAN_2D import CONFIG,RESULT_PATH,InversePIKAN
from _common import boundary,device_from,initial,loss,observations,relative_l2,sample,set_seed,train
def main(device_name=None,mode="hard",trials=None,epochs=None):
 d=device_from(device_name or CONFIG["runtime"]["device"]);q=CONFIG["tuning"];seed=int(CONFIG["reproducibility"]["seed"]);true=float(CONFIG["problem"]["true_diffusivity"]);g=torch.Generator(device=d).manual_seed(seed);inside=sample(q["interior_points"],d,g);data=observations(q["sensor_points"],CONFIG["inverse"]["noise_std"],true,d,g);bc=boundary(q["boundary_points"],d,g);ic=initial(q["initial_points"],d);valid=sample(q["validation_points"],d,g)
 def fn(t):
  set_seed(seed);a=(t.suggest_int("n_layers",q["n_layers"]["min"],q["n_layers"]["max"]),t.suggest_int("n_neurons",q["n_neurons"]["min"],q["n_neurons"]["max"],step=q["n_neurons"]["step"]),t.suggest_int("grid",q["grid"]["min"],q["grid"]["max"]),t.suggest_int("spline_order",q["spline_order"]["min"],q["spline_order"]["max"]));m=InversePIKAN(*a,mode,CONFIG["inverse"],d,seed).to(d);c=dict(CONFIG["training"]);c["epochs"]=int(epochs or q["epochs"]);c["print_every"]=0;train(m,lambda:loss(m,inside,*data,bc,ic,true,CONFIG["loss_weights"]),c);field=float(relative_l2(m,valid,true));parameter=abs(float(m.diffusivity())-true)/true;t.set_user_attr("field_relative_l2",field);t.set_user_attr("parameter_relative_error",parameter);return field+parameter
 s=optuna.create_study(direction="minimize",sampler=optuna.samplers.TPESampler(seed=seed));s.optimize(fn,n_trials=int(trials or q["trials"]));payload=json.loads(RESULT_PATH.read_text()) if RESULT_PATH.exists() else {};payload[mode]={"best_value":s.best_value,"best_params":s.best_params,"best_metrics":s.best_trial.user_attrs};RESULT_PATH.write_text(json.dumps(payload,indent=2));print(f"Saved: {RESULT_PATH}")
if __name__=="__main__":p=argparse.ArgumentParser();p.add_argument("--device",choices=("cpu","gpu"));p.add_argument("--constraint",choices=("hard","soft"),default="hard");p.add_argument("--trials",type=int);p.add_argument("--epochs",type=int);a=p.parse_args();main(a.device,a.constraint,a.trials,a.epochs)
